def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        if history[-1][1] == 'D' and history[-2][1] == 'D':
            return 'D'
        return 'C'
    if n >= 97:
        opp_recent_def = sum(1 for i in range(n - 3, n) if history[i][1] == 'D')
        if opp_recent_def <= 1:
            return 'D'
        return 'C'
    opp_def = 0
    opp_c = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_def += 1
        else:
            opp_c += 1
    my_last = history[-1][0]
    opp_last = history[-1][1]
    opp_prev = history[-2][1]
    if n >= 10:
        recent_opp_def = sum(1 for i in range(n - 10, n) if history[i][1] == 'D')
    else:
        recent_opp_def = opp_def
    if recent_opp_def >= 9:
        return 'D'
    if opp_last == 'D' and opp_prev == 'D':
        if recent_opp_def >= 6:
            return 'D'
        if rng.random() < 0.75:
            return 'D'
        return 'C'
    if opp_last == 'D':
        if my_last == 'C':
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        if rng.random() < 0.5:
            return 'C'
        return 'D'
    if opp_last == 'C':
        if my_last == 'D':
            if rng.random() < 0.7:
                return 'C'
            return 'D'
        if recent_opp_def >= 3:
            if rng.random() < 0.4:
                return 'D'
            return 'C'
        return 'C'
    return 'C'
